import sys
sys.path.insert(0, "model")
import cordic_model as m

lines = [
    "// Auto-generated by scripts/gen_atan.py - do not edit by hand",
    "localparam signed [15:0] X0 = %d;" % m.X0,
    "function signed [15:0] atan_lut(input integer idx);",
    "  case (idx)",
]
for i, a in enumerate(m.ATAN):
    lines.append("    %d: atan_lut = 16'sd%d;" % (i, a))
lines += ["    default: atan_lut = 16'sd0;", "  endcase", "endfunction"]

with open("rtl/cordic_atan.vh", "w") as f:
    f.write("\n".join(lines) + "\n")
print("wrote rtl/cordic_atan.vh")
